parameters.jsCode:
const item = $input.first();
const raw =
  item.json.body ??
  item.json.data ??
  item.json;

let parsed = raw;
if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error('Webhook body is not valid JSON');
  }
} else if (raw && typeof raw === 'object' && typeof raw.body === 'string') {
  parsed = JSON.parse(raw.body);
}

const services = Array.isArray(parsed.services_needed)
  ? parsed.services_needed.join(', ')
  : (parsed.services_needed_text || '');

return [{
  json: {
    submitted_at: parsed.submitted_at || new Date().toISOString(),
    full_name: parsed.full_name || '',
    email: parsed.email || '',
    business_name: parsed.business_name || '',
    organization_type: parsed.organization_type || '',
    industry: parsed.industry || '',
    years_in_business: parsed.years_in_business || '',
    accounting_software: parsed.accounting_software || '',
    books_status: parsed.books_status || '',
    start_timeline: parsed.start_timeline || '',
    transaction_volume: parsed.transaction_volume || '',
    services_needed: services,
    preferred_next_step: parsed.preferred_next_step || '',
    additional_notes: parsed.additional_notes || '',
    message: parsed.message || '',
    source: parsed.source || 'ledgerxtr.com',
    status: parsed.status || 'new',
  },
}];

